+    @Test
+    public void shouldOrderBySubtopologyIdThenByPartition() {
+        final List<TaskId> tasks = new ArrayList<>(List.of(
+            new TaskId("b", 0),
+            new TaskId("a", 10),
+            new TaskId("a", 2),
+            new TaskId("b", 1)
+        ));
+
+        Collections.sort(tasks);
+
+        // Partitions compare as numbers, not as strings: a_2 comes before a_10.
+        assertEquals(
+            List.of(new TaskId("a", 2), new TaskId("a", 10), new TaskId("b", 0), new TaskId("b", 1)),
+            tasks
+        );
+    }
+
+    @Test
+    public void shouldCompareAsEqualOnlyForTheSameTask() {
+        assertEquals(0, new TaskId("a", 1).compareTo(new TaskId("a", 1)));
+        assertTrue(new TaskId("a", 1).compareTo(new TaskId("a", 2)) < 0);
+        assertTrue(new TaskId("a", 2).compareTo(new TaskId("a", 1)) > 0);
+        assertTrue(new TaskId("a", 9).compareTo(new TaskId("b", 0)) < 0);
+    }
